/* portico-row - shadcn/ui theme (Tailwind v4).
   Drop into your global CSS after `@import "tailwindcss";`.
   Values are the identity spec from identity.json. */

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-ok: var(--ok);
  --color-ok-soft: var(--ok-soft);
  --color-ok-foreground: var(--ok-foreground);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-warn-foreground: var(--warn-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --font-display: "Source Serif 4", Georgia, "Times New Roman", serif;
  --font-sans: "Source Sans 3", "Helvetica Neue", Arial, system-ui, sans-serif;
  --font-mono: ui-monospace, Menlo, Consolas, monospace;
  /* radius ladder pinned inside the 0-2px ceiling; xl is pinned, not
     derived (deriving would climb past the ceiling). */
  --radius-sm: 0rem;
  --radius-md: 0.0625rem;
  --radius-lg: 0.125rem;
  --radius-xl: 0.125rem;
}

:root,
[data-theme="portico-row"] {
  --background: #f7f8f9; /* cool paper, gray-cool-2 register */
  --foreground: #202b38; /* cool ink */
  --card: #ffffff;
  --card-foreground: #202b38;
  --popover: #ffffff;
  --popover-foreground: #202b38;
  --primary: #2c608a; /* link/action navy, blue-60 register; 6.7:1 on white */
  --primary-foreground: #ffffff; /* 6.7:1 on the action navy */
  --secondary: #edf0f2; /* sunk band, gray-cool-5 register */
  --secondary-foreground: #202b38;
  --muted: #edf0f2; /* skeletons and quiet fills */
  --muted-foreground: #565c65; /* gray-cool-60; 6.7:1 on white */
  --accent: #edf0f2; /* interactive wash sits in the sunk-band family */
  --accent-foreground: #202b38;
  --destructive: #b50909; /* red-60 register; white on it is 7:1 */
  --destructive-foreground: #ffffff;
  --ok: #316b37; /* institutional green, 6.4:1 with white */
  --ok-soft: #e7efe7;
  --ok-foreground: #27522c; /* 7.7:1 on the soft wash */
  --warn: #8c6d3f; /* the brass register doubles as caution */
  --warn-soft: #f2ecdf;
  --warn-foreground: #6e5430; /* 6:1 on the soft wash */
  --border: #6c7686; /* hairline; 4.6:1 on white, clears the 3:1 hairline law */
  --input: #6c7686;
  --ring: #2c608a; /* focus ring, always visible */
  --radius: 0.125rem; /* 2px ceiling: architecture, not bubbles */
  --font-display: "Source Serif 4", Georgia, "Times New Roman", serif;
  --font-sans: "Source Sans 3", "Helvetica Neue", Arial, system-ui, sans-serif;
  --font-mono: ui-monospace, Menlo, Consolas, monospace;
  /* Brand structure. Navy bands, rules, and the wordmark; it never fills or
     decorates content panels. */
  --navy: #173359; /* brand navy; 12.7:1 with white */
  --navy-deep: #1f303e; /* footer band and dark sections, blue-80 register */
  --wash: #d9e8f6; /* blue-10 tint fills; never under body text */
  --brass: #8c6d3f; /* optional flavor hairlines only; 4.8:1 on white */
  /* dark-band companions: contrast is tokenized, never improvised */
  --band: #1f303e;
  --band-foreground: #ffffff; /* 13.5:1 on the band */
  --band-muted: #a9b4bd; /* 6.4:1 on the band */
  --band-accent: #d9e8f6; /* dark-band CTA fill */
  --band-accent-fg: #1f303e; /* 10.8:1 on the fill */
  color-scheme: light;
}

/* Identity signatures: Source Serif 4 display at display sizes and pull
   quotes only (body is always sans), the 19px body floor, tracked
   small-caps eyebrows, and engraved hairlines instead of shadows. */
h1, h2, .font-display {
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--foreground);
}
h1 { line-height: 1.08; }
h2 { line-height: 1.14; }
/* Component headings stay sans: serif never appears below display sizes. */
h3, h4, h5, h6 {
  font-family: var(--font-sans);
  font-weight: 600;
  letter-spacing: 0;
}
.eyebrow {
  font-family: var(--font-sans);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--navy);
}
.pull-quote {
  font-family: var(--font-display);
  font-style: italic;
  font-size: clamp(24px, 2.6vw, 32px);
  line-height: 1.35;
  letter-spacing: 0;
}
.tabular { font-variant-numeric: tabular-nums; }
body {
  font-family: var(--font-sans);
  font-size: 19px; /* the floor: no body text ships below this */
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}


/* ---- overrides ---- */
/* portico-row overrides - the opinionated treatment on top of stock shadcn.
   Layer AFTER shadcn styles. Each rule is a deliberate identity decision:
   engraved hairlines replace shadows, navy is structure, serif stays at
   display sizes, and focus is always visible. */

/* Buttons are architecture: square 2px corners, flat fills, no shadow, no
   lift. Hover deepens the fill toward brand navy; 200ms ease. Blocks keep
   interactive rows at 44px or taller. */
[data-identity="portico-row"] [data-slot="button"] {
  border-radius: 2px;
  font-weight: 600;
  box-shadow: none;
  transition: background-color 200ms ease, color 200ms ease,
    border-color 200ms ease;
}
[data-identity="portico-row"] [data-slot="button"].bg-primary:hover:not(:disabled) {
  background-color: var(--navy);
}
[data-identity="portico-row"] [data-slot="button"]:disabled {
  opacity: 0.55;
}

/* Cards: square corners with a single engraved hairline. No shadow at any
   elevation - the hairline is the boundary. A hovered card deepens its
   hairline to brand navy instead of lifting. */
[data-identity="portico-row"] [data-slot="card"] {
  border: 1px solid var(--border);
  border-radius: 0;
  box-shadow: none;
}
[data-identity="portico-row"] .hover-lift {
  transition: border-color 200ms ease;
}
[data-identity="portico-row"] .hover-lift:hover [data-slot="card"] {
  border-color: var(--navy);
}

/* Badges: tracked small-caps chips, square corners, hairline boundary.
   shadcn's filled primary badge is neutralized to the navy-on-wash voice so
   action navy keeps doing all the pointing; explicit soft status fills
   (bg-ok-soft, bg-warn-soft) stay. */
[data-identity="portico-row"] [data-slot="badge"] {
  border: 1px solid var(--border);
  border-radius: 2px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
[data-identity="portico-row"] [data-slot="badge"].bg-primary {
  background: var(--wash);
  color: var(--navy);
  border-color: var(--wash);
}

/* Tables read as a record: engraved row rules, tabular figures, tracked
   small-caps headers on the sunk band. */
[data-identity="portico-row"] table {
  font-variant-numeric: tabular-nums;
  border-collapse: separate;
  border-spacing: 0;
}
[data-identity="portico-row"] th {
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted-foreground);
  background: var(--secondary);
}
[data-identity="portico-row"] tbody tr {
  transition: background-color 200ms ease;
}
[data-identity="portico-row"] tbody tr:hover {
  background: var(--secondary);
}

/* Inputs: square 2px corners, engraved hairline, navy focus outline.
   The border-color never flips on focus; the outline carries focus. */
[data-identity="portico-row"] input,
[data-identity="portico-row"] textarea,
[data-identity="portico-row"] select {
  border-radius: 2px;
  transition: box-shadow 200ms ease;
}

/* Focus law: a 2px navy outline, always visible, never removed, never
   color-only. No halo fades. */
[data-identity="portico-row"] :focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

/* Pull quotes: serif italic with the brass hairline. This is the only
   surface brass decorates; body rules and boundaries stay navy/slate. */
[data-identity="portico-row"] blockquote {
  border-left: 2px solid var(--brass);
  padding-left: 24px;
  font-family: var(--font-display);
  font-style: italic;
}

/* Sheet and dialog chrome wear the navy header band: white title, muted
   companion text, and a hairline base. The close control sits on the band,
   so it renders white. */
[data-identity="portico-row"] [data-slot="dialog-header"],
[data-identity="portico-row"] [data-slot="sheet-header"] {
  background: var(--navy);
  color: var(--band-foreground);
  border-bottom: 1px solid rgb(255 255 255 / 0.4);
}
[data-identity="portico-row"] [data-slot="dialog-header"] [data-slot="dialog-title"],
[data-identity="portico-row"] [data-slot="dialog-header"] [data-slot="dialog-description"],
[data-identity="portico-row"] [data-slot="sheet-header"] [data-slot="sheet-title"],
[data-identity="portico-row"] [data-slot="sheet-header"] [data-slot="sheet-description"] {
  color: inherit;
}
[data-identity="portico-row"] [data-slot="dialog-header"] [data-slot="dialog-description"],
[data-identity="portico-row"] [data-slot="sheet-header"] [data-slot="sheet-description"] {
  color: var(--band-muted);
}
[data-identity="portico-row"] [data-slot="dialog-content"],
[data-identity="portico-row"] [data-slot="sheet-content"] {
  border-radius: 0;
  box-shadow: none;
  border: 1px solid var(--border);
}
[data-identity="portico-row"] [data-slot="dialog-close"] {
  color: var(--band-foreground);
}

/* A panning table says so: the numbered first column sticks and an
   engraved hairline marks the pan edge. */
[data-identity="portico-row"] .table-scroll {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
[data-identity="portico-row"] .table-scroll th:first-child {
  position: sticky;
  left: 0;
  background: var(--secondary);
  box-shadow: inset -1px 0 0 var(--border);
}
[data-identity="portico-row"] .table-scroll td:first-child {
  position: sticky;
  left: 0;
  background: var(--card);
  box-shadow: inset -1px 0 0 var(--border);
}
[data-identity="portico-row"] .table-scroll thead th:first-child {
  z-index: 1;
}

import type { ReactNode } from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"

/* Insights and briefings ride the marketing type scale with the full data
   grammar: loading renders skeleton prose, error renders a retry card, and
   an empty body never ships blank. The meta line carries the substance
   pairing (figure + date). */
export function Article({
  eyebrow = "Insights",
  title = "What the new ownership-transparency rules mean for family companies",
  meta = "6 min read · Filed 12 March 2026",
  status = "ready",
  children,
}: {
  eyebrow?: string
  title?: string
  meta?: string
  status?: "ready" | "loading" | "error" | "empty"
  children?: ReactNode
}) {
  return (
    <article className="mx-auto max-w-[760px] px-6 py-20 lg:py-24">
      <p className="eyebrow">{eyebrow}</p>
      <h1 className="mt-4 text-[clamp(30px,3.8vw,44px)]">{title}</h1>
      <p className="mt-4 border-b border-border pb-8 text-[15px] uppercase tracking-[0.1em] text-muted-foreground">
        {meta}
      </p>
      <div className="mt-8 flex flex-col gap-6 text-[19px] leading-[1.65] [&_blockquote]:my-2 [&_h2]:mt-10 [&_h2]:text-[24px] [&_li]:mt-2 [&_ol]:ml-5 [&_ol]:list-decimal [&_ul]:ml-5 [&_ul]:list-disc">
        {status === "loading" && (
          <div aria-label="Loading article">
            {["w-full", "w-11/12", "w-full", "w-4/5", "w-full", "w-3/5"].map((w, i) => (
              <div
                key={i}
                className={`mb-3 h-5 ${w} animate-pulse bg-muted motion-reduce:animate-none`}
              />
            ))}
          </div>
        )}
        {status === "error" && (
          <Card className="py-12">
            <CardContent className="px-10 text-center">
              <h2 className="text-[19px]">This briefing failed to load</h2>
              <p className="mt-2 text-[16px] leading-relaxed text-muted-foreground">
                The piece is safe on our side. Nothing you did caused this.
              </p>
              <Button size="sm" variant="outline" className="mt-5 h-11 px-5">
                Retry
              </Button>
            </CardContent>
          </Card>
        )}
        {status === "empty" && (
          <Card className="py-12">
            <CardContent className="px-10 text-center">
              <h2 className="text-[19px]">Nothing published yet</h2>
              <p className="mt-2 text-[16px] leading-relaxed text-muted-foreground">
                Briefings appear here the moment they are filed.
              </p>
            </CardContent>
          </Card>
        )}
        {status === "ready" && children}
      </div>
    </article>
  )
}

/* Pull quotes are one of the two serif moments below display size; the
   brass hairline is the brass token's only decorating surface. */
export function PullQuote({ children }: { children: ReactNode }) {
  return (
    <blockquote className="pull-quote my-4 text-foreground">
      {children}
    </blockquote>
  )
}

/* Substance figures travel inside prose: the KPI card keeps the numbered
   figure-over-label grammar from the substance strip. */
export function Kpi({ value, label }: { value: string; label: string }) {
  return (
    <Card className="py-5">
      <CardContent className="px-6">
        <b className="font-display text-[30px] font-semibold leading-none tabular-nums">{value}</b>
        <span className="mt-2 block text-[12.5px] font-semibold uppercase tracking-[0.14em] text-muted-foreground">
          {label}
        </span>
      </CardContent>
    </Card>
  )
}

import type { ReactNode } from "react"
import { ArrowRight } from "lucide-react"
import { Button } from "@/components/ui/button"

/* The substance strip is the identity's proof-of-work: tabular serif figures
   over tracked small-caps labels, read left to right under an engraved
   hairline. Every page carries at least one concrete number in this style. */
export function SubstanceStrip({
  stats = [
    { value: "38", label: "years in practice" },
    { value: "$1.9B", label: "transaction value advised" },
    { value: "140", label: "matters closed last year" },
    { value: "3", label: "offices" },
  ],
  loading = false,
}: {
  stats?: { value: string; label: string }[]
  loading?: boolean
}) {
  if (!loading && stats.length === 0) {
    return (
      <dl className="border-t border-border pt-8">
        <dt className="sr-only">Firm record</dt>
        <dd className="text-[17px] text-muted-foreground">
          Figures publish with the next annual statement.
        </dd>
      </dl>
    )
  }
  return (
    <dl className="grid grid-cols-2 gap-x-10 gap-y-8 border-t border-border pt-8 sm:grid-cols-4">
      {loading
        ? Array.from({ length: 4 }).map((_, i) => (
            <div key={i} aria-label="Loading figures">
              <div className="h-8 w-24 animate-pulse bg-muted motion-reduce:animate-none" />
              <div className="mt-2.5 h-3.5 w-20 animate-pulse bg-muted motion-reduce:animate-none" />
            </div>
          ))
        : stats.map((s) => (
            <div key={s.label}>
              <dd className="font-display text-[30px] leading-none tabular-nums">{s.value}</dd>
              <dt className="mt-2.5 text-[12.5px] font-semibold uppercase tracking-[0.14em] text-muted-foreground">
                {s.label}
              </dt>
            </div>
          ))}
    </dl>
  )
}

/* The narrow positioning hero: who you serve, one concrete claim, and a
   single primary CTA (a quiet text link may follow; a second filled button
   never does). Loading keeps the substance strip from popping. */
export function Hero({
  eyebrow = "Business law, practiced since 1987",
  title = "Counsel for companies the region runs on",
  accent,
  description = "Jarndyce & Jarndyce advises founder-led and family-owned businesses on transactions, disputes, and the decisions in between. Every engagement is partner-led, from the first call to the signature.",
  primaryCta = "Request a consultation",
  quietLink = "Our practices",
  note = "No fee for the first conversation.",
  statsLoading = false,
  stats,
  children,
}: {
  eyebrow?: string
  title?: string
  accent?: string
  description?: string
  primaryCta?: string
  quietLink?: string
  note?: string
  statsLoading?: boolean
  stats?: { value: string; label: string }[]
  children?: ReactNode
}) {
  return (
    <section className="mx-auto w-full max-w-[880px] px-6 pb-24 pt-20 lg:pb-28 lg:pt-28">
      <p className="eyebrow">{eyebrow}</p>
      <h1 className="mt-5 max-w-[22ch] text-[clamp(34px,4.6vw,54px)]">
        {title} {accent && <em className="not-italic text-primary">{accent}</em>}
      </h1>
      <p className="mt-6 max-w-[58ch] text-[19px] leading-[1.65] text-muted-foreground">
        {description}
      </p>
      <div className="mt-9 flex flex-wrap items-center gap-x-7 gap-y-3">
        <Button size="lg" className="h-12 px-7 text-[16px]">
          {primaryCta}
          <ArrowRight className="ml-1.5 size-4" aria-hidden />
        </Button>
        {quietLink && (
          <a
            href="#"
            className="text-[16px] font-semibold text-primary underline underline-offset-4 hover:text-[var(--navy)]"
          >
            {quietLink}
          </a>
        )}
      </div>
      {note && <p className="mt-4 text-[15px] text-muted-foreground">{note}</p>}
      <div className="mt-16">{children ?? <SubstanceStrip loading={statsLoading} stats={stats} />}</div>
    </section>
  )
}

"use client"

import { useState, type ReactNode } from "react"
import { ArrowRight, Loader2, Mail, MapPin, Phone } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"

/* This shell frames an institutional marketing page: a navy header band with
   the serif wordmark, children as the section stack, and the compliance
   footer as the credibility sink. The footer is mandatory on every page. */
export function LandingShell({
  brand = "Jarndyce & Jarndyce",
  nav = [
    { label: "Practices" },
    { label: "People" },
    { label: "Insights" },
    { label: "Careers" },
    { label: "Contact" },
  ],
  cta = "Request a consultation",
  footer,
  children,
}: {
  brand?: string
  nav?: { label: string; href?: string; active?: boolean }[]
  cta?: string
  footer?: ReactNode
  children: ReactNode
}) {
  return (
    <div className="min-h-screen bg-background text-foreground">
      <header className="sticky top-0 z-40 bg-[var(--navy)]">
        <div className="mx-auto flex min-h-[72px] max-w-[1120px] flex-wrap items-center gap-x-8 gap-y-1 px-6 py-2 md:h-[72px] md:flex-nowrap md:py-0">
          <a href="#" className="font-display text-[22px] tracking-[-0.01em] text-white max-md:me-auto">
            {brand}
          </a>
          <nav
            className="ml-auto flex items-center gap-7 overflow-x-auto max-md:order-last max-md:w-full max-md:border-t max-md:border-white/25 max-md:pt-1"
            aria-label="Primary"
          >
            {nav.map((n) => (
              <a
                key={n.label}
                href={n.href ?? "#"}
                aria-current={n.active ? "page" : undefined}
                className={`inline-flex min-h-[44px] shrink-0 items-center whitespace-nowrap text-[15px] transition-colors ${
                  n.active
                    ? "font-semibold text-white underline underline-offset-8"
                    : "text-white/80 hover:text-white"
                }`}
              >
                {n.label}
              </a>
            ))}
          </nav>
          <div className="ml-auto shrink-0 md:ml-0">
            <Button
              variant="outline"
              className="h-11 border-white/40 bg-transparent px-4 text-[14px] text-white hover:border-white hover:bg-white/10 hover:text-white"
            >
              <span className="sm:hidden">Consult</span>
              <span className="hidden sm:inline">{cta}</span>
            </Button>
          </div>
        </div>
      </header>

      <main>{children}</main>

      {footer ?? <ComplianceFooter brand={brand} />}
    </div>
  )
}

/* The compliance footer is the identity's credibility sink and is mandatory
   on every page: entity, registrations, offices, disclosure links, and the
   advertising notice. Furniture stays in the deep navy band. */
export function ComplianceFooter({
  brand = "Jarndyce & Jarndyce",
  entity = "A professional limited liability partnership. Counsel for founder-led and family-owned companies.",
  offices = "Offices in Chicago, Milwaukee, and Indianapolis.",
  registrations = "Registered to practice before the courts of the jurisdictions in which our offices sit.",
  links = [
    { label: "Privacy" },
    { label: "Terms of use" },
    { label: "Disclosures" },
    { label: "Accessibility" },
  ],
  notice = "Attorney advertising. Prior results do not guarantee a similar outcome. Nothing on this site is legal advice, and reading it does not create an attorney-client relationship.",
}: {
  brand?: string
  entity?: string
  offices?: string
  registrations?: string
  links?: { label: string; href?: string }[]
  notice?: string
}) {
  return (
    <footer className="bg-[var(--navy-deep)] text-[var(--band-foreground)]">
      <div className="mx-auto max-w-[1120px] px-6 py-16">
        <div className="grid gap-12 lg:grid-cols-[1.4fr_1fr]">
          <div>
            <span className="font-display text-[22px] tracking-[-0.01em]">{brand}</span>
            <p className="mt-4 max-w-[52ch] text-[15px] leading-relaxed text-[var(--band-muted)]">
              {entity}
            </p>
            <p className="mt-6 flex items-start gap-2 text-[15px] text-[var(--band-muted)]">
              <MapPin className="mt-0.5 size-4 shrink-0" aria-hidden />
              {offices}
            </p>
          </div>
          <nav aria-label="Disclosures">
            <h3 className="text-[12.5px] font-semibold uppercase tracking-[0.14em] text-[var(--band-muted)]">
              Disclosures
            </h3>
            <ul className="mt-4 space-y-2.5">
              {links.map((l) => (
                <li key={l.label}>
                  <a
                    href={l.href ?? "#"}
                    className="text-[15px] text-white/85 underline underline-offset-4 hover:text-white"
                  >
                    {l.label}
                  </a>
                </li>
              ))}
            </ul>
          </nav>
        </div>
        <div className="mt-12 border-t border-white/40 pt-6">
